GUIDES = {'1': ['G184', 'G186', 'G233', 'G248'], '2': ['G233', 'G249', 'G234'],
          '3': ['G186', 'G233', 'G249'], '4': ['G184', 'G186', 'G188'],
          '5': ['G248', 'G233'], '6': ['G248', 'G186'], '7': ['G184', 'G233', 'G234']}


def build():
    p, doc = source(VOLUME)
    sections = numbered_sections(doc)
    notes = {}
    for line in NOTES.splitlines():
        if not line.strip():
            continue
        number, *parts = line.split('|')
        if len(parts) != 6 or number in notes:
            raise ValueError((number, len(parts)))
        notes[number] = parts
    actual = {r['title_en'].split(' ', 1)[0].rstrip('.') for r in sections}
    if set(notes) != actual:
        raise ValueError({'missing': sorted(actual - set(notes)), 'extra': sorted(set(notes) - actual)})
    fields = ['concepts_zh', 'applicability_zh', 'logic_zh', 'decisions_zh', 'artifacts_evidence_zh', 'limits_zh']
    result = {'schema_version': 'fundamental-semantic-review/1', 'volume_id': VOLUME,
              'source_document_sha256': sha(p), 'source': doc['source'],
              'review_status': 'source-read-section-analysis-authored-visual-review-separately-authored',
              'review_method_zh': '逐编号标题读取直接正文，区分概念、条件、关系、决定、制品证据及边界；标题分组不制造新规则。源图及HTML表单元格由独立审阅者另存后并入。',
              'sections': [], 'figures': [], 'tables': [],
              'source_issues': [
                  {'id': 'AC-ARTIFACT-DELIVERABLE-CROSSREF', 'section': '1.2.1',
                   'description_zh': '原文specific artifacts to be developed链接Chapter 4 Architecture Deliverables；保留制品与交付物的语义区别，不按该链接将二者合并。'},
                  {'id': 'AC-MARKET-TEMPORAL-SCOPE', 'sections': ['3.3.1', '3.4.3'],
                   'description_zh': '工具市场互操作困难是保存源文判断，本轮不将其解释为2026年实时市场调查结论。'}]}
    for r in sections:
        n = r['title_en'].split(' ', 1)[0].rstrip('.')
        row = {key: r[key] for key in ('heading_id', 'title_en')}
        row.update({field: [value] if value else [] for field, value in zip(fields, notes[n])})
        row.update(source_block_ids=[b['id'] for b in r['blocks']],
                   source_content_sha256=hashlib.sha256('\n'.join(b.get('text_en', '') for b in r['blocks']).encode()).hexdigest(),
                   source_url=doc['source']['url'] + '#' + r['heading_id'],
                   guide_refs=GUIDES.get(n, GUIDES.get(n.split('.')[0], [])),
                   status='authored-source-bound-analysis')
        result['sections'].append(row)
    DATA.mkdir(exist_ok=True)
    dest = DATA / (VOLUME + '.json')
    dest.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n')
    lines = ['# 架构内容：逐节语义解析', '', '来源：本地2025数字版；中文分析为项目解释，不是官方译文或组织批准。', '',
             f"编号标题{len(sections)}，逐节源块及指纹可核对。图表由独立审阅者补入；未以正文阅读计为图表审阅完成。", '']
    for row in result['sections']:
        lines += ['## ' + row['title_en'], '',
                  f"[离线原文](../../fundamental/web-2025/volumes/{VOLUME}/index.html#{row['heading_id']})；源块：" + ', '.join(i.rsplit(':', 1)[-1] for i in row['source_block_ids']), '']
        for field, label in zip(fields, ['概念', '适用条件', '逻辑关系', '决策方法', '制品与证据', '边界']):
            if row[field]:
                lines += [label + '：' + '；'.join(row[field]), '']
        if row['guide_refs']:
            lines += ['指南关联：' + ', '.join(row['guide_refs']), '']
    lines += ['## 源文问题', '']
    lines += [json.dumps(issue, ensure_ascii=False) for issue in result['source_issues']]
    dest.with_suffix('.md').write_text('\n'.join(lines) + '\n')
    print({'sections': len(sections), 'figures_tables': 'independent-root-review-to-merge'})


if __name__ == '__main__':
    build()
